% ============================================================
% content.tex - Simple Circuits Study Notes
% Example-driven notes based primarily on Success Key MC Q5-Q30,
% with Book 4 and 4_ch02_MC_e.pdf used for definitions and checks.
% ============================================================

\section*{Simple Circuits: Read the Circuit Before Using a Formula}

A circuit problem is usually decided before any calculation: identify which points are joined by ideal wire, which components carry the same current, and which components share the same potential difference.

\begin{mdframed}[backgroundcolor=blue!5,leftline=true,linecolor=blue,linewidth=2pt]
\textbf{The three questions to ask first}
\begin{enumerate}[label=\arabic*.,itemsep=3pt,topsep=3pt]
  \item Where can charge flow? A closed path carries current; a gap does not.
  \item Which points are equipotential? Points joined only by ideal wire have the same potential.
  \item Is the connection series or parallel? Series means the same current; parallel means the same p.d.
\end{enumerate}
\end{mdframed}

\section{Current and Charge}

\begin{exercise}
\textbf{Starter problem (adapted from 4\_ch02 MC Q25--Q27).} A lamp carries a steady current of $0.30$ A for 2 minutes. Find the charge passing through it. Does the lamp use up charge?

\textbf{Solution.} Current is the rate of flow of charge:
\[
\boxed{I=\frac{Q}{t}} \qquad \Longrightarrow \qquad Q=It.
\]
Convert time first: $2$ min $=120$ s. Therefore
\[
Q=(0.30)(120)=\boxed{36\text{ C}}.
\]
The lamp does \emph{not} use up charge. In steady operation, 36 C enters the lamp and 36 C leaves it. The lamp transfers electrical energy to light and thermal energy.
\end{exercise}

\begin{center}
\begin{tikzpicture}[x=1cm,y=1cm]
  \draw[thick,->] (0,1) -- (2,1) node[midway,above] {conventional current $I$};
  \draw[thick] (2,0.55) rectangle (4,1.45);
  \node at (3,1) {lamp};
  \draw[thick,->] (4,1) -- (6,1) node[midway,above] {same $I$};
  \node[align=center] at (3,-0.1) {energy changes form; charge is conserved};
\end{tikzpicture}
\end{center}

\textbf{Direction.} Conventional current is drawn from the positive terminal to the negative terminal in the external circuit. Electrons in a metal move in the opposite direction.

\begin{mdframed}[backgroundcolor=red!5,leftline=true,linecolor=red,linewidth=2pt]
\textbf{Common traps}
\begin{itemize}[itemsep=2pt,topsep=3pt]
  \item Use the magnitude of electron charge, $e=1.60\times10^{-19}$ C, when finding current magnitude.
  \item Convert minutes to seconds and mA to A before using $Q=It$.
  \item Charges do not move more slowly after a resistor in a steady series circuit. The current is the same at every point in that path.
\end{itemize}
\end{mdframed}

\section{Potential, Potential Difference and EMF}

Potential is energy per unit positive charge at one point. Potential difference is the energy transferred per unit charge between two points:
\[
\boxed{V=\frac{W}{Q}} \qquad 1\text{ V}=1\text{ J C}^{-1}.
\]

\begin{exercise}
\textbf{Energy-per-charge problem (4\_ch02 MC Q29--Q30).} A cell supplies 12 J when 6 C passes through it. Find its emf. If a 1.0 V resistor carries 0.50 C, how much energy is converted in the resistor?

\textbf{Solution.}
\[
\mathcal E=\frac{W_{\rm supplied}}{Q}=\frac{12}{6}=\boxed{2.0\text{ V}},
\qquad
W_{\rm converted}=VQ=(1.0)(0.50)=\boxed{0.50\text{ J}}.
\]
A source gives energy to charge; a resistor converts electrical energy to other forms.
\end{exercise}

\begin{center}
\begin{tikzpicture}[x=1cm,y=1cm]
  \draw[->] (0,0) -- (8.5,0) node[right] {position around circuit};
  \draw[->] (0,0) -- (0,4.4) node[above] {potential};
  \draw[very thick] (0.7,0.7) -- (1.7,0.7);
  \draw[very thick,->] (1.7,0.7) -- (1.7,3.7) node[midway,right] {cell: rise $\mathcal E$};
  \draw[very thick] (1.7,3.7) -- (4.5,3.7);
  \draw[very thick,->] (4.5,3.7) -- (4.5,2.2) node[midway,right] {$V_1$};
  \draw[very thick] (4.5,2.2) -- (6.5,2.2);
  \draw[very thick,->] (6.5,2.2) -- (6.5,0.7) node[midway,right] {$V_2$};
  \draw[very thick] (6.5,0.7) -- (8,0.7);
\end{tikzpicture}
\end{center}

For a complete loop with an ideal cell,
\[
\boxed{\text{total emf}=\text{sum of potential drops}}.
\]
A component causes no potential change if it is bypassed by an ideal wire.

\begin{exercise}
\textbf{Potential problem (adapted from Success Key Q13).} A 6 V supply is connected across three identical $2\,\Omega$ resistors in series. Point B, at the negative terminal, is earthed. Find the potentials after the first and second resistors when moving from the positive terminal.

\textbf{Solution.} Earthing sets $V_B=0$, but does not by itself change the currents. The three equal resistors share 6 V equally, so each drop is 2 V. The positive terminal is at $+6$ V; the next points are $+4$ V and $+2$ V, then B is 0 V.
\end{exercise}

\section{Terminal Potential Difference}

An ideal source has no internal resistance, so terminal p.d. equals emf. A real source has internal resistance $r$:
\[
\boxed{V_{\rm terminal}=\mathcal E-Ir}.
\]

\begin{exercise}
\textbf{Real-cell problem (Success Key Q14).} A cell of emf 3.0 V and internal resistance $0.50\,\Omega$ supplies 1.0 A. Find its terminal p.d.

\textbf{Solution.}
\[
V_{\rm terminal}=3.0-(1.0)(0.50)=\boxed{2.5\text{ V}}.
\]
The missing 0.5 V is the p.d. across the internal resistance. With no current, $Ir=0$ and the terminal p.d. returns to the emf.
\end{exercise}

\section{Resistance and Ohm's Law}

For any component at a particular operating point,
\[
\boxed{R=\frac{V}{I}}.
\]
An \textbf{ohmic} component at constant temperature has constant $R$, so $V\propto I$. Not every conductor is ohmic: a filament heats up, causing its resistance to change.

\begin{exercise}
\textbf{Direct application (4\_ch02 MC Q18).} A 1.5 V p.d. is applied across a $2.0\,\Omega$ lamp. Find the current, treating its resistance as 2.0 $\Omega$ at this operating point.
\[
I=\frac{V}{R}=\frac{1.5}{2.0}=\boxed{0.75\text{ A}}.
\]
\end{exercise}

\begin{mdframed}[backgroundcolor=yellow!10,leftline=true,linecolor=yellow!60!black,linewidth=2pt]
\textbf{Reading graphs correctly}
\begin{itemize}[itemsep=2pt,topsep=3pt]
  \item On a $V$-against-$I$ graph, the slope is $R$ only for a straight line through the origin.
  \item For a non-ohmic component, the operating resistance at a point is the ratio $V/I$, not automatically the tangent slope.
  \item A filament lamp's resistance increases as it becomes hotter.
\end{itemize}
\end{mdframed}

\section{Resistivity and Wire Dimensions}

For a uniform wire,
\[
\boxed{R=\rho\frac{\ell}{A}}, \qquad A=\pi r^2=\frac{\pi d^2}{4}.
\]
Resistivity $\rho$ is a material property at a stated temperature. The correct unit is $\Omega\,\mathrm m$.

\begin{exercise}
\textbf{Scaling problem (4\_ch02 MC Q35).} A wire of length $\ell$ and diameter $d$ has resistance $10\,\Omega$. A second wire of the same material has length $2\ell$ and diameter $0.5d$. Find its resistance.

The area factor is $(0.5)^2=0.25$. Hence
\[
\frac{R'}{R}=\frac{\ell'}{\ell}\frac{A}{A'}=2\left(\frac{1}{0.25}\right)=8,
\qquad R'=\boxed{80\,\Omega}.
\]
Halving diameter does not merely double resistance; it quarters area and therefore multiplies resistance by four.
\end{exercise}

\begin{exercise}
\textbf{Joined rods (4\_ch02 MC Q7).} Two rods of the same material are joined end-to-end. The first has length $2\ell$, diameter $2d$, and resistance $r$. The second has length $\ell$ and diameter $d$. Find the total resistance.

For the first rod, $r\propto 2\ell/(2d)^2=\ell/(2d^2)$. For the second, $R_2\propto\ell/d^2$, so $R_2=2r$. They are end-to-end, hence in series:
\[
R_{\rm total}=r+2r=\boxed{3r}.
\]
\end{exercise}

\section{Series and Parallel Networks}

\begin{center}
\begin{tikzpicture}[x=1cm,y=1cm]
  \node[font=\bfseries] at (1.8,2.8) {Series};
  \draw[thick] (0,1.8) -- (0.7,1.8);
  \draw[thick] (0.7,1.45) rectangle (2.1,2.15) node[pos=.5] {$R_1$};
  \draw[thick] (2.1,1.8) -- (2.8,1.8);
  \draw[thick] (2.8,1.45) rectangle (4.2,2.15) node[pos=.5] {$R_2$};
  \draw[thick] (4.2,1.8) -- (4.9,1.8);
  \draw[->,blue,thick] (0.2,2.35) -- (4.7,2.35) node[midway,above] {same $I$};

  \node[font=\bfseries] at (7.6,2.8) {Parallel};
  \draw[thick] (5.3,1.8) -- (6,1.8) -- (6,2.4);
  \draw[thick] (6,2.4) -- (6.5,2.4);
  \draw[thick] (6.5,2.05) rectangle (8.1,2.75) node[pos=.5] {$R_1$};
  \draw[thick] (8.1,2.4) -- (8.6,2.4) -- (8.6,1.8) -- (9.3,1.8);
  \draw[thick] (6,1.8) -- (6,1.2) -- (6.5,1.2);
  \draw[thick] (6.5,0.85) rectangle (8.1,1.55) node[pos=.5] {$R_2$};
  \draw[thick] (8.1,1.2) -- (8.6,1.2) -- (8.6,1.8);
  \node[blue] at (7.3,0.35) {same $V$ across both branches};
\end{tikzpicture}
\end{center}

\begin{center}
{\small
\noindent\begin{tabularx}{\linewidth}{p{28mm} X X}
\toprule
 & \textbf{Series} & \textbf{Parallel} \\
\midrule
Identifying test & One unbranched path; shared junction has no other connection & Both ends of each component join the same two nodes \\
Current & Same through every component & Splits and recombines: $I=I_1+I_2+\cdots$ \\
Voltage & $V=V_1+V_2+\cdots$ & Same across every branch \\
Resistance & $R_{\rm eq}=R_1+R_2+\cdots$ & $1/R_{\rm eq}=1/R_1+1/R_2+\cdots$ \\
\bottomrule
\end{tabularx}}
\end{center}

\begin{exercise}
\textbf{Mixed network.} A 3.0 V battery supplies a $4\,\Omega$ resistor in series with a parallel pair of $1\,\Omega$ and $2\,\Omega$. Find the current through the $1\,\Omega$ resistor.

\begin{center}
\begin{tikzpicture}[x=1cm,y=1cm]
  \draw[thick] (0,0) -- (0,2.4) -- (1,2.4);
  \draw[thick] (1,2.05) rectangle (2.5,2.75) node[pos=.5] {$4\,\Omega$};
  \draw[thick] (2.5,2.4) -- (3.2,2.4) -- (3.2,3.1) -- (3.8,3.1);
  \draw[thick] (3.8,2.75) rectangle (5.3,3.45) node[pos=.5] {$1\,\Omega$};
  \draw[thick] (5.3,3.1) -- (5.9,3.1) -- (5.9,2.4);
  \draw[thick] (3.2,2.4) -- (3.2,1.7) -- (3.8,1.7);
  \draw[thick] (3.8,1.35) rectangle (5.3,2.05) node[pos=.5] {$2\,\Omega$};
  \draw[thick] (5.3,1.7) -- (5.9,1.7) -- (5.9,2.4) -- (6.6,2.4) -- (6.6,0) -- (0,0);
  \draw[thick] (0.75,0.15) -- (0.75,-0.15);
  \draw[very thick] (1.1,0.3) -- (1.1,-0.3);
  \node[below] at (0.93,-0.35) {3.0 V};
\end{tikzpicture}
\end{center}

First reduce the parallel pair:
\[
R_p=\frac{(1)(2)}{1+2}=\frac{2}{3}\,\Omega,
\qquad R_{\rm total}=4+\frac{2}{3}=\frac{14}{3}\,\Omega.
\]
Thus $I_{\rm total}=3/(14/3)=9/14$ A. The p.d. across the parallel pair is
\[
V_p=I_{\rm total}R_p=\frac{9}{14}\cdot\frac{2}{3}=\frac{3}{7}\text{ V}.
\]
Therefore
\[
I_{1\Omega}=\frac{V_p}{1}=\boxed{0.429\text{ A}}.
\]
Check: current in the $2\,\Omega$ branch is $0.214$ A; the branch currents add to $0.643$ A.
\end{exercise}

\begin{mdframed}[backgroundcolor=red!5,leftline=true,linecolor=red,linewidth=2pt]
\textbf{Topology traps}
\begin{itemize}[itemsep=2pt,topsep=3pt]
  \item Components that look side-by-side are not necessarily parallel. Compare their two end nodes.
  \item In parallel, the smaller resistance carries the larger current.
  \item $R_{\rm parallel}$ is always smaller than the smallest branch resistance.
\end{itemize}
\end{mdframed}

\section{Ammeter and Voltmeter}

\begin{exercise}
\textbf{Connection problem (4\_ch02 MC Q28 and Q32).} How should current through a resistor and p.d. across it be measured?

\begin{center}
\begin{tikzpicture}[x=1cm,y=1cm]
  \draw[thick] (0,0) -- (0,2.2) -- (1.1,2.2);
  \draw[thick] (1.55,2.2) circle (0.45); \node at (1.55,2.2) {A};
  \draw[thick] (2,2.2) -- (2.7,2.2);
  \draw[thick] (2.7,1.85) rectangle (4.4,2.55) node[pos=.5] {$R$};
  \draw[thick] (4.4,2.2) -- (5.5,2.2) -- (5.5,0) -- (0,0);
  \draw[thick] (2.7,2.2) -- (2.7,3.5) -- (3.1,3.5);
  \draw[thick] (3.55,3.5) circle (0.45); \node at (3.55,3.5) {V};
  \draw[thick] (4,3.5) -- (4.4,3.5) -- (4.4,2.2);
  \draw[thick] (0.8,0.15) -- (0.8,-0.15);
  \draw[very thick] (1.15,0.3) -- (1.15,-0.3);
\end{tikzpicture}
\end{center}

The ammeter is in series so the component current passes through it. An ideal ammeter has $R_A=0$. The voltmeter is in parallel because voltage is measured between two points. An ideal voltmeter has $R_V\to\infty$ and draws no current.
\end{exercise}

\begin{exercise}
\textbf{Why meter placement matters (adapted from Success Key Q20).} A high-resistance voltmeter across points A and B reads 3 V. Replacing it by a low-resistance ammeter connects A and B almost directly by wire. What happens?

The ammeter creates a short path between A and B. Their p.d. becomes approximately zero, and a large current may flow in that path. Never connect an ammeter directly across a cell or component.
\end{exercise}

\begin{mdframed}[backgroundcolor=yellow!10,leftline=true,linecolor=yellow!60!black,linewidth=2pt]
A voltmeter in series behaves approximately as an open circuit. An ammeter in parallel behaves approximately as a short circuit. Use these replacements when predicting a circuit before calculating.
\end{mdframed}

\section{Open and Short Circuits}

\begin{center}
\begin{tikzpicture}[x=1cm,y=1cm]
  \node[font=\bfseries] at (2,2.6) {Open circuit};
  \draw[thick] (0,1.5) -- (1.4,1.5);
  \draw[thick] (1.4,1.5) -- (2.2,2.05);
  \fill (1.4,1.5) circle (2pt); \fill (2.8,1.5) circle (2pt);
  \draw[thick] (2.8,1.5) -- (4,1.5);
  \node at (2,0.8) {$I=0$, but a p.d. may exist across the gap};

  \node[font=\bfseries] at (7,2.6) {Short circuit};
  \draw[thick] (5,1.5) -- (5.8,1.5);
  \draw[thick] (5.8,1.15) rectangle (7.5,1.85) node[pos=.5] {$R$};
  \draw[thick] (7.5,1.5) -- (8.3,1.5);
  \draw[thick] (5.8,1.5) -- (5.8,0.55) -- (7.5,0.55) -- (7.5,1.5);
  \node at (6.7,0) {$V_R=0$; current bypasses $R$};
\end{tikzpicture}
\end{center}

\begin{exercise}
\textbf{Switch problem (Success Key Q25 idea).} Closing a switch places an ideal wire directly across AB. What is the voltage across AB after closing?

Both A and B lie on the same ideal conductor, so they are equipotential:
\[
\boxed{V_{AB}=0}.
\]
Any resistor bypassed by that wire also has zero p.d. and zero current. If the short is across a source, current is limited only by internal and wire resistance and can become dangerously large.
\end{exercise}

\section{Power and Brightness}

Electrical power is the rate of energy transfer:
\[
\boxed{P=VI=I^2R=\frac{V^2}{R}}, \qquad \boxed{W=Pt}.
\]
Choose the form that matches what is held constant.

\begin{exercise}
\textbf{Scaling power (4\_ch02 MC Q12).} A resistor $3R$ connected to emf $V$ dissipates power $P$. Find the power when resistance $R$ is connected to emf $2V$.
\[
P=\frac{V^2}{3R}, \qquad P'=\frac{(2V)^2}{R}=\frac{4V^2}{R}=\boxed{12P}.
